(2246840, 309312, 24454, '<td valign="top">This is such a striking image!! You can actually <i>feel</i> the bitter cold.  Executed with perfection, and one of my favorites in this challenge. 10</td>', 'This is such a striking image!! You can actually feel the bitter cold.  Executed with perfection, and one of my favorites in this challenge. 10', '2006-03-22 07:48:14.000000', NULL, 1),
(2246842, 309654, 24454, '<td valign="top">Very nicely done.  The light in just the right places gives this indeed a glowing effect.   I love how the light tones change from reds to green.   Beautiful photo!</td>', 'Very nicely done.  The light in just the right places gives this indeed a glowing effect.   I love how the light tones change from reds to green.   Beautiful photo!', '2006-03-22 07:49:49.000000', NULL, 1),
(2246847, 309400, 24454, '<td valign="top">One of my favorite birds to photograph.  Excellent choice, and captured very well! Nice detail in the grasses for a dark, low-key image. Good luck!!!</td>', 'One of my favorite birds to photograph.  Excellent choice, and captured very well! Nice detail in the grasses for a dark, low-key image. Good luck!!!', '2006-03-22 07:53:13.000000', NULL, 1),
