(2249228, 309792, 37588, '<td valign="top">This is really neat, although I think I might like it more if you could see a tiny bit more of the eye. Or if the eye were bigger. But really nice</td>', 'This is really neat, although I think I might like it more if you could see a tiny bit more of the eye. Or if the eye were bigger. But really nice', '2006-03-22 20:49:14.000000', NULL, 1),
(2249229, 307494, 43565, '<td valign="top">Would like to see the stairs.</td>', 'Would like to see the stairs.', '2006-03-22 20:49:16.000000', NULL, 1),
(2249248, 309151, 54446, '<td valign="top">You almost had it with this one.  I''ve rated it well.  But, you blew out the light emanating from the center.  Great concept and execution, except for the center overexp.</td>', 'You almost had it with this one.  I''ve rated it well.  But, you blew out the light emanating from the center.  Great concept and execution, except for the center overexp.', '2006-03-22 20:57:54.000000', NULL, 1),
(2249249, 308679, 54446, '<td valign="top">This is almost excellent.  Somehow, you needed to bring the entire image of the ape into sharp clarity, and then it would have been an easy winner in the challenge.  I still rated it very high.</td>', 'This is almost excellent.  Somehow, you needed to bring the entire image of the ape into sharp clarity, and then it would have been an easy winner in the challenge.  I still rated it very high.', '2006-03-22 20:59:16.000000', NULL, 1),
(2249253, 308849, 54446, '<td valign="top">Needed to be the other way around to meet the spirit of the challenge.  As is, it''s a silhouette against a bright sky.</td>', 'Needed to be the other way around to meet the spirit of the challenge.  As is, it''s a silhouette against a bright sky.', '2006-03-22 21:00:25.000000', NULL, 1),
(2249257, 309356, 54446, '<td valign="top">I like the idea.  The light is harsh.  At least you understand the concept.</td>', 'I like the idea.  The light is harsh.  At least you understand the concept.', '2006-03-22 21:02:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2249259, 308671, 54446, '<td valign="top">Wow!  Not sure this is "low key", but it sure is beautiful and emotional.  I''ll rate this very high.  However, would have been much better by moving the horizon off the vertical center line.</td>', 'Wow!  Not sure this is "low key", but it sure is beautiful and emotional.  I''ll rate this very high.  However, would have been much better by moving the horizon off the vertical center line.', '2006-03-22 21:04:23.000000', NULL, 1),
(2249266, 309381, 37588, '<td valign="top">This is gorgeous! The colors are so fantastic. Well done!</td>', 'This is gorgeous! The colors are so fantastic. Well done!', '2006-03-22 21:07:44.000000', NULL, 1),
(2249268, 309556, 54446, '<td valign="top">Great idea!  Wish the light wasn''t so harsh. I like this a lot.</td>', 'Great idea!  Wish the light wasn''t so harsh. I like this a lot.', '2006-03-22 21:08:15.000000', NULL, 1),
(2249272, 307758, 54446, '<td valign="top">Just too overexposed in areas.  Otherwise, this had potential.</td>', 'Just too overexposed in areas.  Otherwise, this had potential.', '2006-03-22 21:10:42.000000', NULL, 1),
(2249274, 309895, 15711, '<td valign="top">EXCELLENT.  This is exemplary for the challenge.  NOt a touch of grain - tack sharp yet minimal light.  WOW - this rocks. Just looked at this again. Giving it a perfect score. It is just amazing. 10</td>', 'EXCELLENT.  This is exemplary for the challenge.  NOt a touch of grain - tack sharp yet minimal light.  WOW - this rocks. Just looked at this again. Giving it a perfect score. It is just amazing. 10', '2006-03-22 21:11:03.000000', NULL, 1),
(2249276, 309465, 54446, '<td valign="top">Super!  The image that probably should be used as an ideal example of "low key".  Well done!  ...and sexy, too.</td>', 'Super!  The image that probably should be used as an ideal example of "low key".  Well done!  ...and sexy, too.', '2006-03-22 21:11:41.000000', NULL, 1),
(2249280, 309808, 54446, '<td valign="top">Nightmarish! and, overexposed for this challenge.</td>', 'Nightmarish! and, overexposed for this challenge.', '2006-03-22 21:12:44.000000', NULL, 1),
(2249282, 309376, 15711, '<td valign="top">This is wonderful!!!!!! Love the whiskers and the eyes.  Great clarity for such low light.  BRAVO I''m bumping up to a 10 - man this is just killer!!!! Congratulations on a terrific image.</td>', 'This is wonderful!!!!!! Love the whiskers and the eyes.  Great clarity for such low light.  BRAVO I''m bumping up to a 10 - man this is just killer!!!! Congratulations on a terrific image.', '2006-03-22 21:13:07.000000', NULL, 1),
