(2249288, 309547, 54446, '<td valign="top">Excellent still life.  Overall underexposed, rather than low key.  I like the presentation, but it DNMC.</td>', 'Excellent still life.  Overall underexposed, rather than low key.  I like the presentation, but it DNMC.', '2006-03-22 21:15:27.000000', NULL, 1),
(2249294, 309773, 54446, '<td valign="top">Underexposed, but I like the subject and composition.  Not sure this is "low key".</td>', 'Underexposed, but I like the subject and composition.  Not sure this is "low key".', '2006-03-22 21:17:28.000000', NULL, 1),
