(2249365, 309827, 54446, '<td valign="top">Very nice!  A very good "low key" image.</td>', 'Very nice!  A very good "low key" image.', '2006-03-22 21:35:56.000000', NULL, 1),
(2249371, 308144, 54446, '<td valign="top">Simply superb!</td>', 'Simply superb!', '2006-03-22 21:37:10.000000', NULL, 1),
