(2249388, 307837, 54446, '<td valign="top">Too much oof, needs clarity.  Otherwise good concept.</td>', 'Too much oof, needs clarity.  Otherwise good concept.', '2006-03-22 21:40:44.000000', NULL, 1),
(2249423, 309560, 34659, '<td valign="top">Absolutely frickin'' awesome!  Beautiful...  If I could give you an 11 I would.</td>', 'Absolutely frickin'' awesome!  Beautiful...  If I could give you an 11 I would.', '2006-03-22 21:52:42.000000', NULL, 1),
(2249427, 308144, 34659, '<td valign="top">Very cool - and very nice job.</td>', 'Very cool - and very nice job.', '2006-03-22 21:53:03.000000', NULL, 1),
(2249429, 309758, 34659, '<td valign="top">Amazing clarity.  Beautiful tones.  Nice work.</td>', 'Amazing clarity.  Beautiful tones.  Nice work.', '2006-03-22 21:53:36.000000', NULL, 1),
(2249436, 308661, 34659, '<td valign="top">This image really stands out.  Phenomenal job.  Certainly gets a 10 from me.  Absolutely beautiful work.</td>', 'This image really stands out.  Phenomenal job.  Certainly gets a 10 from me.  Absolutely beautiful work.', '2006-03-22 21:55:27.000000', NULL, 1),
(2249441, 309779, 34659, '<td valign="top">Loving this!!!  Reminds me of one of grigrigirl''s shots - but different enough to stand on its own merit.  Very nice work.  The tones are spectacular.</td>', 'Loving this!!!  Reminds me of one of grigrigirl''s shots - but different enough to stand on its own merit.  Very nice work.  The tones are spectacular.', '2006-03-22 21:56:26.000000', NULL, 1),
