(2249452, 309895, 34659, '<td valign="top">Great shot!  I think I recognize this model...  Wasn''t she shaving in a previous challenge?  ;-)  Love the hat/outfit and pouty lips - the cigarette certainly fits with the scene too.  Very good job.</td>', 'Great shot!  I think I recognize this model...  Wasn''t she shaving in a previous challenge?  ;-)  Love the hat/outfit and pouty lips - the cigarette certainly fits with the scene too.  Very good job.', '2006-03-22 21:59:06.000000', NULL, 1),
(2249453, 309881, 51802, '<td valign="top">That is TOO funny!  Great shot!</td>', 'That is TOO funny!  Great shot!', '2006-03-22 21:59:27.000000', NULL, 1),
(2249454, 308618, 34659, '<td valign="top">By far, the best "key" shot.  :-)  Great tonal range on the low side.  Nice work.</td>', 'By far, the best "key" shot.  :-)  Great tonal range on the low side.  Nice work.', '2006-03-22 22:00:15.000000', NULL, 1),
