(2249460, 309749, 34659, '<td valign="top">I really like this image.  I keep coming back to it over and over again (and bumping up the score).  I can almost feel the tension in this shot - it''s terrific!  And you nailed the technical low key aspect too.  Great job.</td>', 'I really like this image.  I keep coming back to it over and over again (and bumping up the score).  I can almost feel the tension in this shot - it''s terrific!  And you nailed the technical low key aspect too.  Great job.', '2006-03-22 22:02:18.000000', NULL, 1),
(2249464, 309632, 34659, '<td valign="top">Stunning...  Really outstanding work.</td>', 'Stunning...  Really outstanding work.', '2006-03-22 22:03:15.000000', NULL, 1),
(2249474, 309684, 51802, '<td valign="top">Incredible shot!  The lighting and shadows make the shot and then the clouds put it over the top!</td>', 'Incredible shot!  The lighting and shadows make the shot and then the clouds put it over the top!', '2006-03-22 22:05:23.000000', NULL, 1),
