(2249685, 308244, 26906, '<td valign="top">please do not get this personally, but lighting here is awful. broad light just does not work with puffy chicks</td>', 'please do not get this personally, but lighting here is awful. broad light just does not work with puffy chicks', '2006-03-22 23:19:08.000000', NULL, 1),
