(2250528, 307490, 40840, '<td valign="top">This looks like something out of the wizard of ozz:)</td>', 'This looks like something out of the wizard of ozz:)', '2006-03-23 08:02:23.000000', NULL, 1),
(2250545, 307365, 34192, '<td valign="top">This image works extremely well as a low key image.  The highlights are perfectly exposed.  The subject is interesting (to me at least).  Composition works.  You''ve allowed enough texture in to give depth.  Well done. 9</td>', 'This image works extremely well as a low key image.  The highlights are perfectly exposed.  The subject is interesting (to me at least).  Composition works.  You''ve allowed enough texture in to give depth.  Well done. 9', '2006-03-23 08:29:12.000000', NULL, 1),
(2250548, 309137, 34192, '<td valign="top">Very well exposed.  Dynamic composition, excellent tonal range. 9</td>', 'Very well exposed.  Dynamic composition, excellent tonal range. 9', '2006-03-23 08:29:45.000000', NULL, 1),
(2250551, 309650, 53517, '<td valign="top">I really like this shot but it is not Low-Key.</td>', 'I really like this shot but it is not Low-Key.', '2006-03-23 08:31:22.000000', NULL, 1),
(2250554, 308932, 34192, '<td valign="top">I love this image - it has so much movement.  I can see sharpening artifacts around the guy which could be worked out with advanced editing.  The tonal range is excellent, composition outstanding.  I would burn just a tiny bit in the upper right.  This is one I would hang on my wall.  Excellent work. 10</td>', 'I love this image - it has so much movement.  I can see sharpening artifacts around the guy which could be worked out with advanced editing.  The tonal range is excellent, composition outstanding.  I would burn just a tiny bit in the upper right.  This is one I would hang on my wall.  Excellent work. 10', '2006-03-23 08:32:22.000000', NULL, 1),
(2250555, 308144, 34192, '<td valign="top">Very well done tonal range makes this subject interesting, as does the composition.  8</td>', 'Very well done tonal range makes this subject interesting, as does the composition.  8', '2006-03-23 08:33:36.000000', NULL, 1),
(2250561, 309549, 34192, '<td valign="top">I really like the silhouette here but I feel trapped.  Maybe a slim black border would help make this image seem more finished (I usually hate borders).  I also find the slight tilt to the right capturing my attention as the image has strong horizontal lines.  Fixing that might fix my trapped feeling.  The image is perfectly exposed for the subject and works very well in B&amp;W.  7 - good luck in the challenge!</td>', 'I really like the silhouette here but I feel trapped.  Maybe a slim black border would help make this image seem more finished (I usually hate borders).  I also find the slight tilt to the right capturing my attention as the image has strong horizontal lines.  Fixing that might fix my trapped feeling.  The image is perfectly exposed for the subject and works very well in B&W.  7 - good luck in the challenge!', '2006-03-23 08:38:14.000000', NULL, 1),
(2250564, 309895, 34192, '<td valign="top">Beautifully exposed.  Tonal range and tones used are excellent. 9</td>', 'Beautifully exposed.  Tonal range and tones used are excellent. 9', '2006-03-23 08:38:51.000000', NULL, 1),
