INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2251317, 308371, 53006, '<td valign="top">Very cooool!</td>', 'Very cooool!', '2006-03-23 13:36:51.000000', NULL, 1),
(2251323, 309813, 52336, '<td valign="top">Not enough detail to be evocative of anything.  For me, were it more recognizable, and closer-cropped, it would have been better.</td>', 'Not enough detail to be evocative of anything.  For me, were it more recognizable, and closer-cropped, it would have been better.', '2006-03-23 13:38:06.000000', NULL, 1),
(2251329, 307954, 52336, '<td valign="top">Great idea!  Wish the composition were slightly more distributed somehow, and perhaps more sharpness.  Great picture though.</td>', 'Great idea!  Wish the composition were slightly more distributed somehow, and perhaps more sharpness.  Great picture though.', '2006-03-23 13:38:57.000000', NULL, 1),
(2251332, 307785, 53006, '<td valign="top">Love the frozen drops</td>', 'Love the frozen drops', '2006-03-23 13:39:43.000000', NULL, 1),
(2251336, 309075, 52336, '<td valign="top">A bit too much negative space.  Perhaps much closer cropped, duotone, and off-centre?</td>', 'A bit too much negative space.  Perhaps much closer cropped, duotone, and off-centre?', '2006-03-23 13:40:04.000000', NULL, 1),
(2251351, 309019, 53006, '<td valign="top">The shadows are fab!</td>', 'The shadows are fab!', '2006-03-23 13:43:00.000000', NULL, 1),
(2251353, 309609, 52336, '<td valign="top">Bo Bo isn''t in focus enough, and perhaps there''s too much negative space, but nice idea.</td>', 'Bo Bo isn''t in focus enough, and perhaps there''s too much negative space, but nice idea.', '2006-03-23 13:43:07.000000', NULL, 1),
(2251357, 308090, 52336, '<td valign="top">Really cool image.. love it.</td>', 'Really cool image.. love it.', '2006-03-23 13:43:40.000000', NULL, 1),
(2251361, 309845, 53006, '<td valign="top">Would have been awesome if the apple were more in focus</td>', 'Would have been awesome if the apple were more in focus', '2006-03-23 13:45:41.000000', NULL, 1),
(2251366, 308035, 52336, '<td valign="top">Perhaps adequately low-key (though most of the others are much more low key than this one), but the dead-centred geese (ducks?) detract from the interest, and the lack of focus is damaging to the effect.  Colours are lovely.  Jpeg artefacting is a problem here.</td>', 'Perhaps adequately low-key (though most of the others are much more low key than this one), but the dead-centred geese (ducks?) detract from the interest, and the lack of focus is damaging to the effect.  Colours are lovely.  Jpeg artefacting is a problem here.', '2006-03-23 13:46:10.000000', NULL, 1),
(2251390, 308938, 53006, '<td valign="top">Nice lighting</td>', 'Nice lighting', '2006-03-23 13:51:29.000000', NULL, 1),
(2251398, 309311, 53006, '<td valign="top">Very nice!</td>', 'Very nice!', '2006-03-23 13:52:32.000000', NULL, 1),
(2251403, 307986, 53006, '<td valign="top">Neat!</td>', 'Neat!', '2006-03-23 13:54:20.000000', NULL, 1),
(2251407, 309301, 16402, '<td valign="top">DOF is a bit too tight for me, but still a very nice shot.</td>', 'DOF is a bit too tight for me, but still a very nice shot.', '2006-03-23 13:54:47.000000', NULL, 1),
(2251414, 309875, 16402, '<td valign="top">Composition too cluttered but exposure and focus are good.</td>', 'Composition too cluttered but exposure and focus are good.', '2006-03-23 13:56:13.000000', NULL, 1),
(2251431, 307943, 53006, '<td valign="top">Love the expressions on their faces!</td>', 'Love the expressions on their faces!', '2006-03-23 14:02:50.000000', NULL, 1),
(2251439, 309304, 16402, '<td valign="top">Great effort, really don''t have anything constructive to add. Don''t think I''d change a thing.</td>', 'Great effort, really don''t have anything constructive to add. Don''t think I''d change a thing.', '2006-03-23 14:05:33.000000', NULL, 1),
(2251441, 309746, 53006, '<td valign="top">What is it?</td>', 'What is it?', '2006-03-23 14:05:53.000000', NULL, 1),
(2251442, 309137, 53006, '<td valign="top">Would have been better if you could see more of his face</td>', 'Would have been better if you could see more of his face', '2006-03-23 14:06:17.000000', NULL, 1),
(2251454, 309728, 16402, '<td valign="top">I like the shot in general, but technically it seems a bit noisy and over contrasty.</td>', 'I like the shot in general, but technically it seems a bit noisy and over contrasty.', '2006-03-23 14:09:06.000000', NULL, 1),
(2251457, 309719, 16402, '<td valign="top">Black is not low-key it''s no-key.</td>', 'Black is not low-key it''s no-key.', '2006-03-23 14:10:00.000000', NULL, 1),
(2251460, 308032, 16402, '<td valign="top">Interesting shot. I wish it was a bigger so I could judge more about it''s quality.</td>', 'Interesting shot. I wish it was a bigger so I could judge more about it''s quality.', '2006-03-23 14:10:53.000000', NULL, 1),
(2251462, 309797, 16402, '<td valign="top">Cute idea and exposure is pretty good but it seems slightly out of focus to me.</td>', 'Cute idea and exposure is pretty good but it seems slightly out of focus to me.', '2006-03-23 14:11:28.000000', NULL, 1),
(2251467, 309596, 5792, '<td valign="top">Your image has a nice low-key histogram but I suspect some folks will still not think this is low-key because of the colors. Converting it to B&amp;W would be more convincing to them. That is why you see more low-key images in black and white than in color. The image is a bit on the small size and it does not have as good of sharpness as it could.<br/> <br/>But to show you that great minds think along similar lines here is a picture taken from the same spot as you that I once entered in a challenge:<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=47443" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/159/thumb/47443.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/159/thumb/47443.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/159/thumb/47443.jpg"/></a></td>', 'Your image has a nice low-key histogram but I suspect some folks will still not think this is low-key because of the colors. Converting it to B&W would be more convincing to them. That is why you see more low-key images in black and white than in color. The image is a bit on the small size and it does not have as good of sharpness as it could. But to show you that great minds think along similar lines here is a picture taken from the same spot as you that I once entered in a challenge:', '2006-03-23 14:12:16.000000', NULL, 1),
(2251476, 309452, 16402, '<td valign="top">Pretty good effort. I like the composition and lighting but focus seems just a hair off.</td>', 'Pretty good effort. I like the composition and lighting but focus seems just a hair off.', '2006-03-23 14:13:56.000000', NULL, 1),
