INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2252237, 309592, 55738, '<td valign="top">This nicely turns what wouldn''t be a low key photo into one, I like it...</td>', 'This nicely turns what wouldn''t be a low key photo into one, I like it...', '2006-03-23 17:30:17.000000', NULL, 1),
(2252253, 308273, 36043, '<td valign="top">These silhouettes are absolutely wonderful.  The two profile faces make the image - great capture of the moment.</td>', 'These silhouettes are absolutely wonderful.  The two profile faces make the image - great capture of the moment.', '2006-03-23 17:37:18.000000', NULL, 1),
(2252262, 308706, 36043, '<td valign="top">Simple and effective. Title is great, but I see - Game NOT Cancelled Due to Rain.  Good job.</td>', 'Simple and effective. Title is great, but I see - Game NOT Cancelled Due to Rain.  Good job.', '2006-03-23 17:39:23.000000', NULL, 1),
(2252271, 308158, 36043, '<td valign="top">This image really spoke to me.  I was an oil painter for years - haven''t done any recently.  Love the image.   Especially the shadow detail.</td>', 'This image really spoke to me.  I was an oil painter for years - haven''t done any recently.  Love the image.   Especially the shadow detail.', '2006-03-23 17:42:09.000000', NULL, 1),
(2252273, 308706, 46601, '<td valign="top">great shot .. love the detail the "crispness"</td>', 'great shot .. love the detail the "crispness"', '2006-03-23 17:42:53.000000', NULL, 1),
(2252276, 309684, 36043, '<td valign="top">Best Low-Key Landscape in the set.  Impressive.  If the original scales up appropriately, you have something to frame .</td>', 'Best Low-Key Landscape in the set.  Impressive.  If the original scales up appropriately, you have something to frame .', '2006-03-23 17:43:32.000000', NULL, 1),
(2252283, 309151, 36043, '<td valign="top">Excellent Low-Key Color.  Few were able to pull this off well.</td>', 'Excellent Low-Key Color.  Few were able to pull this off well.', '2006-03-23 17:44:30.000000', NULL, 1),
(2252291, 308371, 36043, '<td valign="top">Nicely done.   Probably the best allegory - Good story, composition.</td>', 'Nicely done.   Probably the best allegory - Good story, composition.', '2006-03-23 17:46:10.000000', NULL, 1),
(2252304, 309073, 36043, '<td valign="top">Gotta love this.  Good color in a low-key image.  Perhaps a touch more shadow detail might provide more of a story.  I''d bet original has more.</td>', 'Gotta love this.  Good color in a low-key image.  Perhaps a touch more shadow detail might provide more of a story.  I''d bet original has more.', '2006-03-23 17:48:50.000000', NULL, 1),
(2252313, 309599, 36043, '<td valign="top">Like the story.   Just a little too much contrast (IMO). Some softer transitions (additional light soure or reflector) might link the image tone and mood more closely.   Still one of my highest scores.</td>', 'Like the story.   Just a little too much contrast (IMO). Some softer transitions (additional light soure or reflector) might link the image tone and mood more closely.   Still one of my highest scores.', '2006-03-23 17:51:43.000000', NULL, 1),
(2252315, 308258, 36043, '<td valign="top">Love the blond and red colors mixed in to the black / shadows.  This works very well.  Great composition too.  Bump it up.</td>', 'Love the blond and red colors mixed in to the black / shadows.  This works very well.  Great composition too.  Bump it up.', '2006-03-23 17:52:59.000000', NULL, 1),
(2252317, 308144, 36043, '<td valign="top">Best Macro submission in the lot.  Well done.</td>', 'Best Macro submission in the lot.  Well done.', '2006-03-23 17:53:43.000000', NULL, 1),
(2252334, 309895, 36043, '<td valign="top">Good work - I''d like to see some shadow detail (say with a reflector), but just a small amount to keep the off center composition.  Choice of format  might work even better I think.  Still great.</td>', 'Good work - I''d like to see some shadow detail (say with a reflector), but just a small amount to keep the off center composition.  Choice of format  might work even better I think.  Still great.', '2006-03-23 17:59:25.000000', NULL, 1),
(2252335, 309560, 36043, '<td valign="top">Simple yet effective.  Keeping this near the top.</td>', 'Simple yet effective.  Keeping this near the top.', '2006-03-23 17:59:49.000000', NULL, 1),
