(2255336, 308906, 19944, '<td valign="top">"Low key describes a mostly dark image, with few highlights."<br/> <br/>I''m not seeing that happening here.</td>', '"Low key describes a mostly dark image, with few highlights." I''m not seeing that happening here.', '2006-03-24 14:39:09.000000', NULL, 1),
(2255337, 307859, 19944, '<td valign="top">That light is really harsh on the eyes.</td>', 'That light is really harsh on the eyes.', '2006-03-24 14:39:35.000000', NULL, 1),
