(2255342, 308258, 43405, '<td valign="top">This is one of my two 10s in the challenge. Think the lighting and composure is brilliant. Vey well done, predict a top finish.</td>', 'This is one of my two 10s in the challenge. Think the lighting and composure is brilliant. Vey well done, predict a top finish.', '2006-03-24 14:41:24.000000', NULL, 1),
(2255346, 307440, 13719, '<td valign="top">wow, thats different very cool, I like the shot alot, I''m guess thats lighting in the clouds, great shot nice catch, maybe a tad darker and a little crop from the top some<br/> <br/>very different usually see storm photos from the ground</td>', 'wow, thats different very cool, I like the shot alot, I''m guess thats lighting in the clouds, great shot nice catch, maybe a tad darker and a little crop from the top some very different usually see storm photos from the ground', '2006-03-24 14:43:35.000000', NULL, 1),
(2255350, 308473, 53964, '<td valign="top">I''d have liked the man a little farther either direction, more against the wall or against the bright, to avoid the wall line running into his head. Probably back, because his sharp silhouette draws my eye.</td>', 'I''d have liked the man a little farther either direction, more against the wall or against the bright, to avoid the wall line running into his head. Probably back, because his sharp silhouette draws my eye.', '2006-03-24 14:45:14.000000', NULL, 1),
