(2255354, 309895, 13719, '<td valign="top">I love this shot, B&amp;W is awesome, I love the lighting and how it lights up here face just enough to see her hand and cig and then how it fades to black..... thats just awesome.</td>', 'I love this shot, B&W is awesome, I love the lighting and how it lights up here face just enough to see her hand and cig and then how it fades to black..... thats just awesome.', '2006-03-24 14:48:51.000000', NULL, 1),
(2255355, 309151, 53964, '<td valign="top">The light appears liquid as it flows from the bottom of the shell and down her arms. And when going beyond the obvious a whole second image appears...</td>', 'The light appears liquid as it flows from the bottom of the shell and down her arms. And when going beyond the obvious a whole second image appears...', '2006-03-24 14:49:06.000000', NULL, 1),
(2255356, 309430, 21197, '<td valign="top">Backlighting != Low Key</td>', 'Backlighting != Low Key', '2006-03-24 14:50:19.000000', NULL, 1),
