(2255415, 308890, 19944, '<td valign="top">Low key is characterized by few highlights.  This has a fair amount of highlight.</td>', 'Low key is characterized by few highlights.  This has a fair amount of highlight.', '2006-03-24 15:08:38.000000', NULL, 1),
(2255417, 308710, 19944, '<td valign="top">To me, this is simply a black &amp; white photo.  Low key is characterized by few highlights.</td>', 'To me, this is simply a black & white photo.  Low key is characterized by few highlights.', '2006-03-24 15:09:23.000000', NULL, 1),
