(2257566, 309798, 48672, '<td valign="top">interesting</td>', 'interesting', '2006-03-25 10:31:24.000000', NULL, 1),
(2257567, 308277, 36499, '<td valign="top">You chose a very good subject but i see a few things that need a bit of help. first there looks to be a soft focus on the entire image. I would have liked to have seen a sharp focus either on the edge of the violin(I think thats what this is..sorry if im wrong here) or where the strings and bow meet. Second there is a bit too much light for this subject to meet the challenge. a faster shutter time would have fixed this. U did a great job on composistion. you have key elements in the perfect places that allows the eyes to easily move around this image without getting bored. and border is great(not distracting at all and simple) job well done and good luck<br/>~~Cher~~ :o)</td>', 'You chose a very good subject but i see a few things that need a bit of help. first there looks to be a soft focus on the entire image. I would have liked to have seen a sharp focus either on the edge of the violin(I think thats what this is..sorry if im wrong here) or where the strings and bow meet. Second there is a bit too much light for this subject to meet the challenge. a faster shutter time would have fixed this. U did a great job on composistion. you have key elements in the perfect places that allows the eyes to easily move around this image without getting bored. and border is great(not distracting at all and simple) job well done and good luck~~Cher~~ :o)', '2006-03-25 10:31:27.000000', NULL, 1),
(2257569, 309378, 48672, '<td valign="top">Great pic. The combination of b&amp;w and something classic (traditional, old) is perfect</td>', 'Great pic. The combination of b&w and something classic (traditional, old) is perfect', '2006-03-25 10:33:14.000000', NULL, 1),
