(2268360, 309749, 43714, '<td valign="top">I knew this would ribbon..Beautiful shot.</td>', 'I knew this would ribbon..Beautiful shot.', '2006-03-29 01:56:00.000000', NULL, 0),
(2268362, 309356, 29442, '<td valign="top">I appreciate all the comments (and the scores) :) This is my highest score and ranking yet! I edited this picture on my laptop and I was disappointed when I saw it on my regular monitor that it appeared much darker. So those with LCD monitors probably saw the subtle detail in the right side that people with regular monitors couldn''t (as some of the comments noted).<br/> <br/>I personally really liked this picture and I want to re-take it with a little more light to make sure the right side comes through on the print. For the light I set a 2x3 softbox on the floor and propped up a halogen flashlight (actually an otoscope handle light) to shine through it in a darkened room.</td>', 'I appreciate all the comments (and the scores) :) This is my highest score and ranking yet! I edited this picture on my laptop and I was disappointed when I saw it on my regular monitor that it appeared much darker. So those with LCD monitors probably saw the subtle detail in the right side that people with regular monitors couldn''t (as some of the comments noted). I personally really liked this picture and I want to re-take it with a little more light to make sure the right side comes through on the print. For the light I set a 2x3 softbox on the floor and propped up a halogen flashlight (actually an otoscope handle light) to shine through it in a darkened room.', '2006-03-29 01:56:27.000000', NULL, 0),
(2268485, 309779, 34114, '<td valign="top">Thanks to everyone who voted and commented. I was really unsure of this photo. Felt it had too much shimmer. Guess I got carried away with the shimmer powder. However the way her eyes looked made me enter the challenge.</td>', 'Thanks to everyone who voted and commented. I was really unsure of this photo. Felt it had too much shimmer. Guess I got carried away with the shimmer powder. However the way her eyes looked made me enter the challenge.', '2006-03-29 02:27:40.000000', NULL, 0),
(2268511, 307365, 43434, '<td valign="top">This is great .. score well .. but I am surprised it didn''t do better.</td>', 'This is great .. score well .. but I am surprised it didn''t do better.', '2006-03-29 02:34:45.000000', NULL, 0);
