(2268521, 308671, 43434, '<td valign="top">Love this shot ... well done ..</td>', 'Love this shot ... well done ..', '2006-03-29 02:36:08.000000', NULL, 0),
(2268525, 309632, 15711, '<td valign="top">Well deserved. Congrats!!!</td>', 'Well deserved. Congrats!!!', '2006-03-29 02:37:12.000000', NULL, 0),
(2268552, 308277, 13829, '<td valign="top">Hi everyone!<br/>I would like to thank everybody who left a comment for me. This was my first submission on DPC, and yay, I got into the first 100 :) Yeah, I''m such a dork :)<br/>deepfrog17,justamistere: I agree with you, too much light. I know that now. ;)</td>', 'Hi everyone!I would like to thank everybody who left a comment for me. This was my first submission on DPC, and yay, I got into the first 100 :) Yeah, I''m such a dork :)deepfrog17,justamistere: I agree with you, too much light. I know that now. ;)', '2006-03-29 02:42:36.000000', NULL, 0),
(2268553, 307883, 43434, '<td valign="top">Well done, nicely taken and well meets the challenge.</td>', 'Well done, nicely taken and well meets the challenge.', '2006-03-29 02:43:12.000000', NULL, 0),
