(2269739, 309895, 33068, '<td valign="top">Excellent finish once again.  Well done!</td>', 'Excellent finish once again.  Well done!', '2006-03-29 11:57:28.000000', NULL, 0),
(2269748, 307883, 5792, '<td valign="top">Congrats on the "top 30" finish. ;) You got above a 6.1 and that is a really good score. I''d take that score on an image any day. You are on a tear with high scoring images lately.<br/> <br/>This is one of the few higher placing pictures I scored lower than the group average. I gave it a 6. It is a nice subject with dramatic lighting and from a good perspective. I did not score it higher because the partial desaturation method used in post processing made the image look underexposed and flat to me, particularly on the near tower. As a result the fine detail in the shadows was not drawn out as well to my eye and that is what I like best about low-key images.</td>', 'Congrats on the "top 30" finish. ;) You got above a 6.1 and that is a really good score. I''d take that score on an image any day. You are on a tear with high scoring images lately. This is one of the few higher placing pictures I scored lower than the group average. I gave it a 6. It is a nice subject with dramatic lighting and from a good perspective. I did not score it higher because the partial desaturation method used in post processing made the image look underexposed and flat to me, particularly on the near tower. As a result the fine detail in the shadows was not drawn out as well to my eye and that is what I like best about low-key images.', '2006-03-29 12:00:37.000000', NULL, 0),
(2269751, 309137, 33068, '<td valign="top">Congrats on your top 10 finish.   Great lighting and expression.</td>', 'Congrats on your top 10 finish.   Great lighting and expression.', '2006-03-29 12:01:53.000000', NULL, 0),
