(2303006, 309512, 37893, '<td valign="top">Congrats on a top placement here bud! The lighting is perfect and the emotional appeal is spot on.</td>', 'Congrats on a top placement here bud! The lighting is perfect and the emotional appeal is spot on.', '2006-04-11 02:31:36.000000', NULL, 0),
(2303343, 309843, 42125, '<td valign="top">I like the Moo better :-)</td>', 'I like the Moo better :-)', '2006-04-11 10:37:00.000000', NULL, 0),
(2303381, 309843, 50641, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Gunnsi:</b></div><hr/><i> I like the Moo better :-) </i></td></tr></table> <br/> <br/>Ah, sorry to disappoint, but I couldn''t get the cows into my library ;-)</td>', 'Originally posted by Gunnsi: I like the Moo better :-)   Ah, sorry to disappoint, but I couldn''t get the cows into my library ;-)', '2006-04-11 11:04:47.000000', NULL, 0),
(2305890, 308258, 21816, '<td valign="top">Great photo. The lighting is fantastic! Don''t be too put off by the 1''s you received. It''s just the web site conservatives having their say. Really well done and I hope you keep entering!</td>', 'Great photo. The lighting is fantastic! Don''t be too put off by the 1''s you received. It''s just the web site conservatives having their say. Really well done and I hope you keep entering!', '2006-04-12 07:15:57.000000', NULL, 0),
(2322089, 308656, 51373, '<td valign="top">Impressive shot. Creative lighting! Any bride would love a photo like this.</td>', 'Impressive shot. Creative lighting! Any bride would love a photo like this.', '2006-04-18 14:52:30.000000', NULL, 0),
(2332604, 308997, 21430, '<td valign="top">Fabulous shot. <br/> <br/>  The only change I would make is to remove/replace the black border entirely. With this shot, the black border causes the image to bleed into the border area, which doesn''t do the shot so much justice. <br/> <br/>  A white border or no border would be best for this image.</td>', 'Fabulous shot.    The only change I would make is to remove/replace the black border entirely. With this shot, the black border causes the image to bleed into the border area, which doesn''t do the shot so much justice.    A white border or no border would be best for this image.', '2006-04-21 12:25:03.000000', NULL, 0),
(2336182, 309151, 48570, '<td valign="top">Wonderful light and details. Great capture! Regards, B.</td>', 'Wonderful light and details. Great capture! Regards, B.', '2006-04-23 09:15:10.000000', NULL, 0),
(2336874, 308619, 30982, '<td valign="top">Goran - this was one of my favorites from the challenge - I suspect some thought it wasn''t low key, but I loved it.  Well captured and well presented!</td>', 'Goran - this was one of my favorites from the challenge - I suspect some thought it wasn''t low key, but I loved it.  Well captured and well presented!', '2006-04-23 17:18:03.000000', NULL, 0),
(2339444, 309019, 48570, '<td valign="top">Nice motif. Beautiful play with light and shadows. Excellent capture! Regards, B.</td>', 'Nice motif. Beautiful play with light and shadows. Excellent capture! Regards, B.', '2006-04-24 14:22:42.000000', NULL, 0),
(2346303, 309019, 18219, '<td valign="top">you just left a comment on one of my pictures, so I thought I''d return the favor......<br/>i like the picture a lot.<br/>the black and white is perfect.<br/>even the angled window is spot on.<br/>it''s a shame that you couldn''t have gotten just the mountains in the background and not those line of cars.<br/>that would have made the picture near on perfect.</td>', 'you just left a comment on one of my pictures, so I thought I''d return the favor......i like the picture a lot.the black and white is perfect.even the angled window is spot on.it''s a shame that you couldn''t have gotten just the mountains in the background and not those line of cars.that would have made the picture near on perfect.', '2006-04-26 13:07:54.000000', NULL, 0),
(2354607, 308273, 51125, '<td valign="top">Truly spectacular.  I would not change a thing.  The sense of anticipation and peering in is incredible.  Degas would love it.<br/> <br/>Thanks for the comments on the lines and crows.<br/> <br/>Joh<br/> <br/>PS.  Just added you to my favorites.</td>', 'Truly spectacular.  I would not change a thing.  The sense of anticipation and peering in is incredible.  Degas would love it. Thanks for the comments on the lines and crows. Joh PS.  Just added you to my favorites.', '2006-04-28 22:47:58.000000', NULL, 0),
(2361050, 309679, 42984, '<td valign="top">Scored well, it is a good low key shot but perhaps not different enought to set the world alight</td>', 'Scored well, it is a good low key shot but perhaps not different enought to set the world alight', '2006-04-30 04:55:11.000000', NULL, 0),
(2377805, 309019, 48739, '<td valign="top">I lik ehtis one alot i like how long the ray of light is comming in the window....well done</td>', 'I lik ehtis one alot i like how long the ray of light is comming in the window....well done', '2006-05-03 15:04:52.000000', NULL, 0),
(2378897, 308656, 58173, '<td valign="top">i love it</td>', 'i love it', '2006-05-03 19:14:55.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2380185, 309151, 25355, '<td valign="top">Shell photos seem to be quite common in challenges. This is one of the more creative, better ones. Well done.</td>', 'Shell photos seem to be quite common in challenges. This is one of the more creative, better ones. Well done.', '2006-05-03 23:33:15.000000', NULL, 0),
(2382928, 308258, 41931, '<td valign="top">you got a *10* from me.<br/>nuf said.</td>', 'you got a *10* from me.nuf said.', '2006-05-04 19:28:15.000000', NULL, 0),
(2385502, 309019, 40679, '<td valign="top">hey actually I like this one a lot! it doesn''t matter what kind of camera you have actually, it''s the photographer that makes the photo. and you did!<br/> <br/>I like it, really do. even the tilted frame looks like it was planned and really fits the photo. black &amp; white fits great too and the contrast is perfect. I think you did a great job!</td>', 'hey actually I like this one a lot! it doesn''t matter what kind of camera you have actually, it''s the photographer that makes the photo. and you did! I like it, really do. even the tilted frame looks like it was planned and really fits the photo. black & white fits great too and the contrast is perfect. I think you did a great job!', '2006-05-05 16:41:50.000000', NULL, 0),
(2406025, 309019, 52336, '<td valign="top">A lovely low-key image.  I think the balance of highlight to dark is excellent, and the soft highlight and shadow of the window pane on the floor disappearing toward the user is very satisfying.  The thicker, central pane is a perfect catch for the eye, from which one wants to look all over the image.  I might have preferred the scene out the window to be slightly in bokeh.  A great image.</td>', 'A lovely low-key image.  I think the balance of highlight to dark is excellent, and the soft highlight and shadow of the window pane on the floor disappearing toward the user is very satisfying.  The thicker, central pane is a perfect catch for the eye, from which one wants to look all over the image.  I might have preferred the scene out the window to be slightly in bokeh.  A great image.', '2006-05-11 13:29:02.000000', NULL, 0),
(2407053, 307883, 42013, '<td valign="top">Great night shot!  I wish the sky had a touch more ambient light just to set off the shape of the church better.  Nice job.</td>', 'Great night shot!  I wish the sky had a touch more ambient light just to set off the shape of the church better.  Nice job.', '2006-05-11 19:36:36.000000', NULL, 0),
(2415300, 309019, 30982, '<td valign="top">I rated this one pretty highly in the challenge - definitely one of the better shots.  I liked the angle, I liked the shadow/leading lines.  Very well composed and exposed.</td>', 'I rated this one pretty highly in the challenge - definitely one of the better shots.  I liked the angle, I liked the shadow/leading lines.  Very well composed and exposed.', '2006-05-14 21:36:50.000000', NULL, 0),
(2418410, 309019, 38267, '<td valign="top">Very nice shot here.  You nailed the exposure and that''s not always an easy thing to do with such a contrast of lighting.  The detail outside of the window would have been washed out for many folks.  I also like the slight slant in the angle of the overall shot.  Great work and one of my favorites in your portfolio.</td>', 'Very nice shot here.  You nailed the exposure and that''s not always an easy thing to do with such a contrast of lighting.  The detail outside of the window would have been washed out for many folks.  I also like the slight slant in the angle of the overall shot.  Great work and one of my favorites in your portfolio.', '2006-05-15 18:41:41.000000', NULL, 0),
(2450102, 309019, 40921, '<td valign="top">I really like this photo, especially the shadow play from the window. The only things I can see that might improve it is maybe leveling the window and making the parking lot in the background bokeh.</td>', 'I really like this photo, especially the shadow play from the window. The only things I can see that might improve it is maybe leveling the window and making the parking lot in the background bokeh.', '2006-05-23 15:28:03.000000', NULL, 0),
(2460711, 308273, 37961, '<td valign="top">I can''t get enough of this photo. It is just so compelling and enchanting. I never tire of looking at it.</td>', 'I can''t get enough of this photo. It is just so compelling and enchanting. I never tire of looking at it.', '2006-05-26 18:17:48.000000', NULL, 0),
(2462049, 307883, 34659, '<td valign="top">Very majestic old lady!  Love the POV/perspective and mood you''ve established with the lighting/processing.  Cool.</td>', 'Very majestic old lady!  Love the POV/perspective and mood you''ve established with the lighting/processing.  Cool.', '2006-05-27 15:27:39.000000', NULL, 0),
(2462423, 308523, 48115, '<td valign="top">just love this.. you should be very proud of this stuff man!</td>', 'just love this.. you should be very proud of this stuff man!', '2006-05-27 20:43:30.000000', NULL, 0),
(2462581, 309543, 37730, '<td valign="top">Wonderful.</td>', 'Wonderful.', '2006-05-27 22:29:32.000000', NULL, 0),
(2467251, 309019, 40667, '<td valign="top">Read your comments and i pretty much agree. Although, I think if you CAN make the image appear better, you should. It''s like anything else... do it to the best of your ability eh?</td>', 'Read your comments and i pretty much agree. Although, I think if you CAN make the image appear better, you should. It''s like anything else... do it to the best of your ability eh?', '2006-05-29 22:20:37.000000', NULL, 0),
(2475775, 309019, 55782, '<td valign="top">I love this photo.  I even like that it is a bit crooked.  I works for me. I love the contrast.  Well done.</td>', 'I love this photo.  I even like that it is a bit crooked.  I works for me. I love the contrast.  Well done.', '2006-06-01 11:20:14.000000', NULL, 0),
(2486001, 307943, 55355, '<td valign="top">CUTE!!!</td>', 'CUTE!!!', '2006-06-05 09:25:00.000000', NULL, 0),
(2486636, 309019, 41794, '<td valign="top">Nice use of leading lines...the shadow on the floor leads you to the window. I like the fact that it is not exactly level, I think the slight tilt adds to the photo rather than detracts from it.</td>', 'Nice use of leading lines...the shadow on the floor leads you to the window. I like the fact that it is not exactly level, I think the slight tilt adds to the photo rather than detracts from it.', '2006-06-05 14:08:25.000000', NULL, 0),
(2523308, 309650, 57886, '<td valign="top">Absolutely stunning colors... Great picture :o)</td>', 'Absolutely stunning colors... Great picture :o)', '2006-06-16 20:56:49.000000', NULL, 0),
(2526665, 307748, 51538, '<td valign="top">Well for not doing anything nasty to the studio, and better for being a nicely captured image.  Nice lighting.  Hope to see some more of your work too.</td>', 'Well for not doing anything nasty to the studio, and better for being a nicely captured image.  Nice lighting.  Hope to see some more of your work too.', '2006-06-18 18:50:40.000000', NULL, 0),
(2541002, 308618, 20530, '<td valign="top">Chris,<br/>This is my favorite image of yours. You nailed it in every respect. The composition, lighting, processing. It''s seamless. Also love the subject matter. What a great pun! Congratulations on the high score.<br/> <br/>Sorry to see your portfolio is gone. I''m hoping that you''ll have a change of heart, some day, and come back with more of your unusual and entertaining works. Your comments and enthusiasm have been more inspiring than I can express.<br/> <br/>Cheers,<br/>Roxanne</td>', 'Chris,This is my favorite image of yours. You nailed it in every respect. The composition, lighting, processing. It''s seamless. Also love the subject matter. What a great pun! Congratulations on the high score. Sorry to see your portfolio is gone. I''m hoping that you''ll have a change of heart, some day, and come back with more of your unusual and entertaining works. Your comments and enthusiasm have been more inspiring than I can express. Cheers,Roxanne', '2006-06-22 13:13:16.000000', NULL, 0),
(2545381, 308917, 48739, '<td valign="top">Well i did vote on this shot i gave it an "8" i agree with the crop on the bottom should be made to take of some of the blur. I think this shot was Under rated as well.  Very well done i like the color change on the lighting on the wet road, gives the street light effect.</td>', 'Well i did vote on this shot i gave it an "8" i agree with the crop on the bottom should be made to take of some of the blur. I think this shot was Under rated as well.  Very well done i like the color change on the lighting on the wet road, gives the street light effect.', '2006-06-23 14:37:24.000000', NULL, 0),
(2546374, 308273, 60799, '<td valign="top">The blue in this is stunning...  Nice work.</td>', 'The blue in this is stunning...  Nice work.', '2006-06-23 19:54:33.000000', NULL, 0),
(2582809, 307937, 27133, '<td valign="top">Nice angle and colours.</td>', 'Nice angle and colours.', '2006-07-04 08:00:19.000000', NULL, 0),
(2612078, 308905, 55330, '<td valign="top">this would be great to hide in the background of a photo , a signature of sorts , maybee a series  ALiEn</td>', 'this would be great to hide in the background of a photo , a signature of sorts , maybee a series  ALiEn', '2006-07-11 21:09:33.000000', NULL, 0),
(2632225, 309376, 28742, '<td valign="top">Just a bit dark to me. Seems like it has potential though. Maybe if the cat was thrown on a rooftop? ;-)</td>', 'Just a bit dark to me. Seems like it has potential though. Maybe if the cat was thrown on a rooftop? ;-)', '2006-07-18 04:04:16.000000', NULL, 0),
(2845520, 308997, 44579, '<td valign="top">I didn''t even realize I had voted on this photo while I was reading the description. I rated it a 10. I love your story. I am feeling drawn to photography with meaning. Not just ''technically'' superior photos. True emotion is something of a rarity in our rich and fake culture. Thank you for the inspiration.</td>', 'I didn''t even realize I had voted on this photo while I was reading the description. I rated it a 10. I love your story. I am feeling drawn to photography with meaning. Not just ''technically'' superior photos. True emotion is something of a rarity in our rich and fake culture. Thank you for the inspiration.', '2006-09-18 17:00:55.000000', NULL, 0),
(2845929, 308997, 2158, '<td valign="top">I can''t believe it''s the first time I''ve seen this wonderful shot.  I just can''t find the time to vote on all the entries any more and somehow I always seem to miss the best.  I''m really surprised it didn''t score higher.</td>', 'I can''t believe it''s the first time I''ve seen this wonderful shot.  I just can''t find the time to vote on all the entries any more and somehow I always seem to miss the best.  I''m really surprised it didn''t score higher.', '2006-09-18 20:31:01.000000', NULL, 0),
(2865192, 309512, 60862, '<td valign="top">Wow, is that one gorgeous shot.  Can you have Bec talk to my wife? ;)</td>', 'Wow, is that one gorgeous shot.  Can you have Bec talk to my wife? ;)', '2006-09-26 03:25:31.000000', NULL, 0),
(2865458, 309632, 43405, '<td valign="top">Yep. Can see why you picked this as one of your personal favorites. Ribbon well deserved.<br/> <br/>Evan</td>', 'Yep. Can see why you picked this as one of your personal favorites. Ribbon well deserved. Evan', '2006-09-26 08:11:20.000000', NULL, 0),
